set -eu
root=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 61
test -S "$root/deploy/secrets/userbot_verify.sock" || exit 62
python3 -B - <<'PY'
import asyncio,json,uuid,sys
from pathlib import Path
sock=Path("/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot/deploy/secrets/userbot_verify.sock")
async def query():
 r,w=await asyncio.wait_for(asyncio.open_unix_connection(str(sock)),5)
 try:
  request_id=uuid.uuid4().hex
  q={"request_id":request_id,"action":"video_sale_readback","chat_id":-1002373696859,
     "thread_id":4650,"message_ids":[4689,4690,4691]}
  w.write((json.dumps(q)+"\n").encode());await w.drain()
  data=await asyncio.wait_for(r.readline(),45)
  if not data:sys.exit(64)
  answer=json.loads(data)
  if answer.get("request_id")!=request_id:sys.exit(65)
  if answer.get("status")!="PASS":sys.exit(66)
  if "free_spoiler_flags" not in answer:sys.exit(67)
  if "free_caption_present" not in answer:sys.exit(68)
  if answer.get("free_media_types")!=["MessageMediaPhoto","MessageMediaDocument"]:sys.exit(69)
  if answer.get("free_spoiler_flags")==[True,True]:sys.exit(81)
  if answer.get("free_spoiler_flags")==[False,False]:sys.exit(0)
  if answer.get("free_spoiler_flags")==[True,False]:sys.exit(82)
  if answer.get("free_spoiler_flags")==[False,True]:sys.exit(83)
  sys.exit(84)
 finally:w.close();await w.wait_closed()
try:asyncio.run(query())
except TimeoutError:sys.exit(70)
except ConnectionError:sys.exit(71)
except json.JSONDecodeError:sys.exit(72)
except Exception:sys.exit(79)
PY
echo RESIDENT_FREE_ALBUM_SPOILER=NONE
